it('preserves a rejected string as the hook error cause and caller rejection', async () => {
  const reason = 'string boom';
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw reason;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  let seen: Error | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {onError: async (_session, error) => void (seen = error)},
  });
  const rejection = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({rejection, message: seen?.message, cause: seen?.cause}).toEqual({
    rejection: reason,
    message: reason,
    cause: reason,
  });
});
